<?php
if(getenv('SWIMLOG_SYNTHETIC_TEST')!=='1')throw new RuntimeException('Disposable test flag required.');
require_once dirname(__DIR__).'/app/Auth.php';require_once dirname(__DIR__).'/app/Goals.php';require_once dirname(__DIR__).'/app/CalendarView.php';
use SwimlogStandalone\Auth;use SwimlogStandalone\Goals;use SwimLogEvaluation\Database;use SwimLogEvaluation\Swim_Goals;
$owner=wp_create_user('standalone_goal_owner_'.wp_generate_password(8,false),wp_generate_password(32));$other=wp_create_user('standalone_goal_other_'.wp_generate_password(8,false),wp_generate_password(32));
if(is_wp_error($owner)||is_wp_error($other))throw new RuntimeException('Synthetic goal users could not be created.');
$owner=(int)$owner;$other=(int)$other;(new WP_User($owner))->add_cap('swimlog_view_own_results');(new WP_User($owner))->add_cap('swimlog_manage_own_workouts');(new WP_User($owner))->add_cap('swimlog_manage_all_users');(new WP_User($other))->add_cap('swimlog_view_own_results');(new WP_User($other))->add_cap('swimlog_manage_own_workouts');
wp_set_current_user($owner);$_COOKIE[LOGGED_IN_COOKIE]=wp_generate_auth_cookie($owner,time()+3600,'logged_in');
$now=current_time('mysql');$today=wp_date('Y-m-d',null,wp_timezone());$start=(new DateTimeImmutable($today,wp_timezone()))->modify('-3 days')->format('Y-m-d');$end=$today;$after=(new DateTimeImmutable($today,wp_timezone()))->modify('+1 day')->format('Y-m-d');$due=(new DateTimeImmutable($today,wp_timezone()))->modify('+7 days')->format('Y-m-d');$workoutIds=array();$goalIds=array();$checks=0;$check=static function($ok,$message)use(&$checks){++$checks;if(!$ok)throw new RuntimeException($message);};
$insertWorkout=static function($user,$type,$date,$distance,$unit)use($now,&$workoutIds){global $wpdb;$row=array('user_id'=>$user,'workout_type'=>$type,'workout_start'=>$date.' 08:00:00','total_distance_m'=>is_numeric($distance)?($unit==='yd'?(float)$distance*0.9144:(float)$distance):null,'original_distance'=>$distance,'original_distance_unit'=>$unit,'pool_length_unit'=>$type==='pool'?$unit:null,'created_at'=>$now,'updated_at'=>$now);Database::write('insert',Database::table('workouts'),$row);$id=(int)$wpdb->insert_id;$workoutIds[]=array($id,(int)$user);return$id;};
$create=static function($input)use($owner,$due,$today,&$goalIds){$input+=array('goal_type'=>Swim_Goals::SINGLE,'course_unit'=>'m','start_date'=>$today,'end_date'=>$due);$r=Goals::submit($owner,array_merge($input,array('nonce'=>wp_create_nonce('standalone_goal_save'))),'https://swimlog.example.test','https://swimlog.example.test');if(is_wp_error($r))return$r;global $wpdb;$goalIds[]=(int)$wpdb->insert_id;return (int)$wpdb->insert_id;};
try {
    $insertWorkout($owner,'pool',$start,1000,'m');$insertWorkout($owner,'open_water',$end,500,'m');$insertWorkout($owner,'pool',$end,1000,'yd');$insertWorkout($owner,'running',$end,5000,'m');$insertWorkout($owner,'pool',$after,700,'yd');$insertWorkout($owner,'pool',$after,1300,'m');$insertWorkout($owner,'pool',$end,null,null);$insertWorkout($other,'pool',$end,4000,'m');
    $mGoal=$create(array('goal_type'=>Swim_Goals::PERIOD,'course_unit'=>'m','target_distance'=>'1500','start_date'=>$start,'end_date'=>$after,'title'=>'Synthetic meter period'));$yGoal=$create(array('goal_type'=>Swim_Goals::PERIOD,'course_unit'=>'yd','target_distance'=>'1200','start_date'=>$start,'end_date'=>$after,'title'=>'Synthetic yard period'));
    $singleComplete=$create(array('goal_type'=>Swim_Goals::PERIOD,'single_workout'=>'1','course_unit'=>'m','target_distance'=>'900','start_date'=>$start,'end_date'=>$after,'title'=>'Synthetic single workout complete'));
    $singlePending=$create(array('goal_type'=>Swim_Goals::PERIOD,'single_workout'=>'1','course_unit'=>'m','target_distance'=>'1500','start_date'=>$start,'end_date'=>$after,'title'=>'Synthetic single workout pending'));
    $check(is_int($mGoal)&&is_int($yGoal)&&is_int($singleComplete)&&is_int($singlePending),'Cumulative and Single Workout date-range goals save.');$loaded=Goals::load($owner);$byId=array();foreach($loaded['goals']as$g)$byId[$g['id']]=$g;
    $check(abs($byId[$mGoal]['progress_native']-1500)<0.001&&abs($byId[$mGoal]['progress_meters']-1500)<0.001&&$byId[$mGoal]['status']==='achieved','Meter goal stops at its first qualifying pool/open-water swim and excludes later yard and next-day swims.');
    $check($byId[$mGoal]['completion_date']===$end,'Meter goal records the first swim date that completes the goal.');
    $check(abs($byId[$yGoal]['progress_native']-1200)<0.001,'Yard goal displays its capped canonical meter progress in yards.');
    $check(abs($byId[$yGoal]['progress_meters']-(1200*0.9144))<0.001,'Yard goal caps canonical progress at its 1200 yd target.');
    $check(abs($byId[$yGoal]['target_native']-1200)<0.001,'Yard goal displays its 1200 yd target in yards.');
    $check(abs($byId[$yGoal]['progress_percent']-100)<0.001,'Yard goal percentage stops at completion.');
    $check($byId[$yGoal]['status']==='achieved','Yard goal status compares canonical progress and target.');
    $check($byId[$yGoal]['completion_date']===$end,'Yard goal records the date of the swim that crosses its target.');
    $check($byId[$mGoal]['goal_type']===Swim_Goals::PERIOD,'Unchecked Single Workout option retains cumulative date-range behavior.');
    $check($byId[$singleComplete]['goal_type']===Swim_Goals::SINGLE_WORKOUT&&abs($byId[$singleComplete]['progress_meters']-900)<0.001&&$byId[$singleComplete]['progress_percent']===100.0&&$byId[$singleComplete]['completion_date']===$start&&$byId[$singleComplete]['status']==='achieved','Single Workout completion uses the first qualifying workout date, caps progress at the target, and ignores later larger swims.');
    $check($byId[$singlePending]['goal_type']===Swim_Goals::SINGLE_WORKOUT&&abs($byId[$singlePending]['progress_meters']-1300)<0.001&&abs($byId[$singlePending]['progress_percent']-86.7)<0.001&&$byId[$singlePending]['completion_date']===null&&$byId[$singlePending]['status']==='in_progress','An uncompleted Single Workout goal displays only the longest individual swim, not the cumulative total.');
    $swim=$insertWorkout($owner,'pool',$today,1500,'m');Database::write('insert',Database::table('performances'),array('user_id'=>$owner,'workout_id'=>$swim,'distance_value'=>1500,'course_unit'=>'m','stroke'=>'BR','duration_ms'=>1700000,'evaluation_version'=>'synthetic','achieved_at'=>$now,'created_at'=>$now));
    $distanceOnly=$create(array('course_unit'=>'m','target_distance_value'=>'1500','target_pace'=>'','start_date'=>$start));$paceOnly=$create(array('course_unit'=>'yd','target_distance_value'=>'','target_pace'=>'1:00.00'));
    $ydSwim=$insertWorkout($owner,'pool',$today,400,'yd');Database::write('insert',Database::table('performances'),array('user_id'=>$owner,'workout_id'=>$ydSwim,'distance_value'=>400,'course_unit'=>'yd','stroke'=>'FR','duration_ms'=>240000,'evaluation_version'=>'synthetic','achieved_at'=>$now,'created_at'=>$now));
    $both=$create(array('course_unit'=>'m','target_distance_value'=>'1500','target_pace'=>'2:00.00','start_date'=>$start));
    $laterPerformance=$insertWorkout($owner,'pool',$after,null,null);Database::write('insert',Database::table('performances'),array('user_id'=>$owner,'workout_id'=>$laterPerformance,'distance_value'=>1500,'course_unit'=>'m','stroke'=>'BR','duration_ms'=>1600000,'evaluation_version'=>'synthetic','achieved_at'=>$after.' 08:00:00','created_at'=>$now));
    $check(is_int($distanceOnly)&&is_int($paceOnly)&&is_int($both),'Distance-only, pace-only, and combined one-time goals save.');$loaded=Goals::load($owner);$byId=array();foreach($loaded['goals']as$g)$byId[$g['id']]=$g;
    $check($byId[$distanceOnly]['status']==='achieved'&&$byId[$both]['status']==='achieved','Exact meter distance performance qualifies at any pace and stroke.');
    $check($byId[$distanceOnly]['completion_date']===$today&&$byId[$both]['completion_date']===$today,'One-time goals retain the first qualifying date when a later performance is faster.');
    $check($byId[$paceOnly]['status']==='achieved'&&$byId[$paceOnly]['progress_distance_value']===400&&$byId[$paceOnly]['completion_date']===$today,'Pace-only goal checks evaluated yard pace and records its qualifying swim date.');
    $check(is_wp_error(Goals::submit($owner,array('nonce'=>wp_create_nonce('standalone_goal_save'),'goal_type'=>Swim_Goals::SINGLE,'course_unit'=>'m','target_distance_value'=>'','target_pace'=>'','end_date'=>$due),'https://swimlog.example.test','https://swimlog.example.test')),'Empty one-time targets are rejected.');
    $foreign=Swim_Goals::create($other,array('goal_type'=>Swim_Goals::PERIOD,'course_unit'=>'m','target_distance'=>'10','start_date'=>$start,'end_date'=>$end));$check(!is_wp_error($foreign),'Foreign synthetic goal created for isolation check.');
    $check(is_wp_error(Goals::load($other)),'Manage-all capability cannot load another owner goals in standalone.');
    $delete=Goals::delete($owner,array('nonce'=>wp_create_nonce('standalone_goal_delete'),'goal_id'=>(string)$foreign['id']),'https://swimlog.example.test','https://swimlog.example.test');$check(is_wp_error($delete),'Owner-scoped deletion cannot delete another swimmer goal.');
    $markers=Goals::calendarMarkers($owner,$start,$due);$pairs=array_map(static function($m){return$m['id'].':'.$m['marker'];},$markers);
    $check(in_array($mGoal.':goal_start',$pairs,true)&&in_array($mGoal.':goal_end',$pairs,true)&&in_array($singleComplete.':goal_start',$pairs,true)&&in_array($singleComplete.':goal_end',$pairs,true)&&in_array($both.':goal_due',$pairs,true),'Calendar marks cumulative and Single Workout date-range boundaries and one-time due dates.');
    $goals=$loaded;ob_start();require dirname(__DIR__).'/app/goals.php';$html=ob_get_clean();$check(strpos($html,'Set Goal')!==false&&strpos($html,'List Goals')!==false&&strpos($html,'Synthetic meter period')!==false&&strpos($html,'goal_delete')!==false,'Standalone Goals screen renders set/list controls, live progress and per-goal deletion.');
    $check(strpos($html,'goal-achieved-date')!==false&&strpos($html,Goals::formatCompletionDate($end))!==false,'Goals list shows the completion date beneath each achieved status.');
    $check(strpos($html,'SINGLE-WORKOUT DISTANCE')!==false&&strpos($html,'Longest workout:')!==false,'Goals list labels Single Workout mode and its individual-workout progress.');
    WP_CLI::success('Standalone synthetic goals storage, native-course progress, one-time targets, ownership and calendar checks passed '.$checks.' assertions.');
} finally {
    global $wpdb;
    foreach($goalIds as$id)Database::write('delete',Database::table('goals'),array('id'=>$id,'user_id'=>$owner));
    if(isset($foreign)&&!is_wp_error($foreign))Swim_Goals::delete_for_user($foreign['id'],$other);
    foreach($workoutIds as$entry){$id=$entry[0];$user=$entry[1];Database::write('delete',Database::table('performances'),array('workout_id'=>$id,'user_id'=>$user));Database::write('delete',Database::table('workouts'),array('id'=>$id,'user_id'=>$user));}
    require_once ABSPATH.'wp-admin/includes/user.php';wp_delete_user($owner);wp_delete_user($other);wp_set_current_user(0);unset($_COOKIE[LOGGED_IN_COOKIE]);
}
